pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCaller, address newOwner) public {
        // Bound: ownerCaller and newOwner must be non-zero and distinct from admin
        vm.assume(ownerCaller != address(0) && newOwner != address(0));
        // Set up the owner as a different address from admin
        vm.prank(address(this)); // admin is the deployer (this contract)
        c.setOwner(ownerCaller);
        // Now the owner (ownerCaller) attempts to change owner
        vm.prank(ownerCaller);
        try c.setOwner(newOwner) returns (bool success) {
            // If the call succeeds, we check whether owner changed
            // In correct contract, this call MUST revert because ownerCaller is not admin
            // In buggy contract, this call may succeed and change owner to newOwner
            // Assert: if the call succeeded, owner must NOT have changed in correct version
            // But we can only observe actual state: after owner call, owner must stay as ownerCaller (correct)
            // The bug would set owner to newOwner. So assert: owner remains ownerCaller
            assertEq(c.owner(), ownerCaller);
        } catch {
            // Revert is expected in correct contract. Nothing to check further.
            assertTrue(true);
        }
    }
}

