pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // 1. The only constraint: the admin is the one who deployed the contract,
        //    so we prank as the address that c records as admin to avoid revert.
        //    We can obtain it via a public getter: c.admin() is auto-generated
        //    for the private admin. But private variable has no getter.
        //    The deployer (this contract) is the admin. We can prank as address(this).
        vm.prank(address(this));
        // 2. Call setOwner with the fuzzed _owner address.
        //    Use try/catch to handle potential reverts and capture the return value.
        bool success;
        try c.setOwner(_owner) returns (bool returned) {
            success = returned;
        } catch {
            // If it reverts, we consider it as not applicable for the property.
            // We simply skip the assertion (or assert true for revert case).
            // To keep the property universal only for successful calls,
            // we must not fail on reverts (which are allowed for non-admin).
            // But we already pranked as admin, so it should NOT revert.
            // However, if for some reason fuzzer supplies an address that
            // triggers a revert (e.g., self-destruct? No), it will still be
            // safe to skip.
            success = true; // placeholder to not fail on revert
        }
        // 3. Assert: the returned value (if not reverted) must be exactly true.
        //    The mutant returns false, so it will fail this assertion.
        assertTrue(success == true);
    }
}

