contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        address currentOwner = c.owner();
        vm.prank(actor);
        c.setOwner(actor);
        address newOwner = c.owner();

        // In the reference contract, only the admin can change the owner.
        // Since 'actor' is not the original deployer (admin), the owner must remain unchanged.
        // The buggy version bypasses this check, so fuzzer can find an actor that changes the owner.
        assertTrue(newOwner == currentOwner);
    }
}

