pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this)); // exclude the deployer (admin) to test non-admin behavior
        // Ensure caller is not the default admin (deployer) so the reference must fail
        address originalOwner = c.owner();
        vm.prank(caller);
        bool ok = true;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, a non-admin call must either revert or leave owner unchanged.
        // The bug bypasses the revert and allows the change. We check: if it didn't revert, it must be the bug,
        // because the reference would have reverted. This property holds for every admissible input.
        assertTrue(ok == false || c.owner() == originalOwner);
    }
}
